SELECT block_number,hex(block_hash) AS block_hash_hex,hex(batch_id) AS batch_id_hex,block_time,finality,canonical,committed,quote_coverage,expected_quotes,actual_quotes FROM dex_block FINAL WHERE chain_id=1 AND manifest_hash=unhex('e5493d29bf16f2d7665e90163eda323e2e7a2847e4bd3e7563db77ac11bfe567') AND block_time >= '2026-10-01 12:00:00' AND finality='finalized' AND canonical AND committed AND quote_coverage='complete' ORDER BY block_number DESC LIMIT 1 FORMAT JSONEachRow
